using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;
namespace NightLens {
static class ThemeTests {
    static IEnumerable<Control> Walk(Control root){foreach(Control child in root.Controls){yield return child;foreach(var item in Walk(child))yield return item;}}
    static double Linear(int x){double value=x/255.0;return value<=.04045?value/12.92:Math.Pow((value+.055)/1.055,2.4);}
    static double Luminance(Color c){return .2126*Linear(c.R)+.7152*Linear(c.G)+.0722*Linear(c.B);}
    static double Contrast(Color a,Color b){double x=Luminance(a),y=Luminance(b);return (Math.Max(x,y)+.05)/(Math.Min(x,y)+.05);}
    public static void Run(Forecast forecast,DateTime date,string[] args,List<string> log){Action<bool,string> check=(ok,message)=>{if(!ok)throw new Exception(message);log.Add("PASS: "+message);};check(Conditions.Dew(10,8)=="High"&&Conditions.Dew(10,5)=="Medium"&&Conditions.Dew(10,4)=="Low"&&Conditions.Dew(null,4)=="Not forecast","Dew risk uses High/Medium/Low with correct boundary and missing-data behavior");check(Conditions.Clouds(20)==ConditionLevel.Good&&Conditions.Clouds(21)==ConditionLevel.Medium&&Conditions.Clouds(50)==ConditionLevel.Medium&&Conditions.Clouds(51)==ConditionLevel.Poor&&Conditions.Clouds(null)==ConditionLevel.Unknown,"Cloud colors use the stated 20/50 percent boundaries and keep missing data neutral");check(Conditions.Seeing(3)==ConditionLevel.Good&&Conditions.Seeing(4)==ConditionLevel.Medium&&Conditions.Seeing(5)==ConditionLevel.Medium&&Conditions.Seeing(6)==ConditionLevel.Poor&&Conditions.Seeing(null)==ConditionLevel.Unknown,"Seeing colors match the existing good/fair/poor forecast bands");string folder=Path.GetDirectoryName(args[3]);using(var form=new MainForm(true)){form.LoadTest(forecast,date);form.Show();Application.DoEvents();foreach(string mode in new[]{"Light","Dark","Night"}){form.ChangeTheme(mode);Application.DoEvents();check(Style.Theme==mode&&form.BackColor==Style.Bg,mode+" theme applies immediately to dashboard");check(Contrast(Style.Text,Style.Card)>=4.5&&Contrast(Style.ButtonText,Style.Accent)>=4.5&&Contrast(Style.DisabledText,Style.DisabledBg)>=4.5,mode+" text, navigation and disabled navigation meet 4.5:1 contrast");check(Contrast(Style.BadgeText,Style.BadgeBg)>=4.5,mode+" beginner badge has readable contrast");check(new[]{ConditionLevel.Good,ConditionLevel.Medium,ConditionLevel.Poor}.All(level=>Contrast(Conditions.ColorFor(level),Style.Card)>=4.5),mode+" condition colors meet 4.5:1 text contrast");check(Walk(form).OfType<StatusText>().Any(block=>block.Rows.Any(row=>row.Runs.Any(run=>run.Level==ConditionLevel.Good))),mode+" dashboard includes colored seeing and cloud values");var badges=Walk(form).Where(c=>Equals(c.Tag,"beginner-badge")).ToList();for(int step=0;step<2&&badges.Count==0;step++){var next=Walk(form).OfType<Button>().FirstOrDefault(button=>button.Text=="Next ›"&&button.Enabled);if(next==null)break;next.PerformClick();Application.DoEvents();badges=Walk(form).Where(c=>Equals(c.Tag,"beginner-badge")).ToList();}check(badges.Count>0,mode+" displays prominent beginner badges");foreach(var badge in badges){var card=badge.Parent.Parent;var cardRect=form.RectangleToClient(card.RectangleToScreen(card.ClientRectangle));var badgeRect=form.RectangleToClient(badge.RectangleToScreen(badge.ClientRectangle));check(badgeRect.X>cardRect.X+cardRect.Width/2&&badgeRect.Y-cardRect.Y<40&&cardRect.Contains(badgeRect),mode+" beginner badge fits the card top-right corner");}using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(folder,mode+" theme preview.png"),System.Drawing.Imaging.ImageFormat.Png);}using(var equipment=new EquipmentForm(new Settings())){equipment.Show();Application.DoEvents();check(equipment.BackColor==Style.Bg&&Walk(equipment).OfType<TextBox>().All(t=>t.BackColor==Style.Card&&t.ForeColor==Style.Text),mode+" theme also applies to settings inputs");equipment.Close();}using(var guidance=CaptureUI.Create(new Night(new Settings(),forecast,date).Picks[0].Guide)){guidance.Show();Application.DoEvents();check(!Walk(guidance).OfType<TabControl>().Any(),mode+" capture guidance avoids native white tab strips and borders");var sections=Walk(guidance).OfType<SectionButton>().ToList();check(sections.Any(section=>section.Text=="Capture plan"),mode+" capture guidance uses the Capture plan heading");check(sections.Count==3,mode+" capture guidance retains all three sections");foreach(var section in sections){section.PerformClick();Application.DoEvents();var text=Walk(guidance).OfType<TextBox>().Single();check(section.Selected&&text.Text.Length>30&&text.BackColor==Style.Card&&text.ForeColor==Style.Text,mode+" "+section.Text+" section displays readable themed content");using(var image=new Bitmap(guidance.Width,guidance.Height)){guidance.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(folder,mode+" capture "+section.Text.Replace(" & ","-")+" preview.png"),System.Drawing.Imaging.ImageFormat.Png);}}guidance.Close();}if(mode=="Night")check(new[]{Style.Text,Style.Muted,Style.ButtonText,Style.BadgeText}.All(c=>c.R>c.G*2&&c.R>c.B*2&&Math.Abs(c.G-c.B)<=1),"Night theme uses red rather than amber text and accents");}form.Close();}var settings=Json.Read<Settings>(Json.Write(new Settings{Theme="Night"}));check(settings.Theme=="Night","Appearance preference survives settings serialization");Style.SetTheme("Dark");}
}
}




